"""Helpers shared by the emitters."""

from __future__ import annotations

import re

from .ir import IR, ModelDef, Type

GENERATOR_VERSION = "1"


def header_lines(ir: IR) -> list[str]:
    return [
        "Generated by contracts/tools/codegen/generate.py - DO NOT EDIT.",
        f"Contract version {ir.version}, inputs sha256:{ir.input_hash}, generator v{GENERATOR_VERSION}.",
    ]


def deps_of(t: Type) -> set[str]:
    if t.kind in ("model", "enum"):
        return {t.ref}
    if t.kind == "array" and t.items is not None:
        return deps_of(t.items)
    return set()


def topo_models(ir: IR) -> list[ModelDef]:
    """Models in dependency order (dependencies first), ties broken by name."""
    done: set[str] = set()
    out: list[ModelDef] = []

    def visit(name: str) -> None:
        if name in done:
            return
        done.add(name)
        m = ir.models[name]
        deps = set()
        for f in m.fields:
            deps |= deps_of(f.type)
        if isinstance(m.additional, Type):
            deps |= deps_of(m.additional)
        for d in sorted(deps):
            if d in ir.models:
                visit(d)
        out.append(m)

    for name in sorted(ir.models):
        visit(name)
    return out


def camel(s: str) -> str:
    parts = [p for p in re.split(r"[^0-9A-Za-z]+", s) if p]
    if not parts:
        return "_"
    head = parts[0][:1].lower() + parts[0][1:]
    out = head + "".join(p[:1].upper() + p[1:] for p in parts[1:])
    if out[0].isdigit():
        out = "_" + out
    return out


def upper_snake(s: str) -> str:
    return re.sub(r"[^0-9A-Za-z]+", "_", s).strip("_").upper()


def doc_lines(text: str | None, width: int = 96) -> list[str]:
    if not text:
        return []
    words = text.replace("\r", "").split()
    lines: list[str] = []
    cur = ""
    for w in words:
        if cur and len(cur) + 1 + len(w) > width:
            lines.append(cur)
            cur = w
        else:
            cur = f"{cur} {w}" if cur else w
    if cur:
        lines.append(cur)
    return lines


def field_attr_name(json_name: str, ns_key: str | None) -> str:
    """Language-neutral base name; namespaced keys use the namespace value key instead."""
    return ns_key if ns_key else json_name
